#!/usr/bin/env python3
"""Finalize the readable source package and an additive Workspace import manifest."""
from __future__ import annotations
import argparse,hashlib,json,shutil
from datetime import datetime,timezone
from pathlib import Path
from render_support import render

def descriptor(path: Path,root: Path) -> dict:
    return {'path':path.relative_to(root).as_posix(),'bytes':path.stat().st_size,
      'sha256':hashlib.file_digest(path.open('rb'),'sha256').hexdigest()}

def prepare(root: Path) -> dict:
    for name in ('import_support.py','prepare_handoff.py','render_support.py'):
        original=Path(__file__).parent/name;target=root/'source'/name
        if original.resolve()!=target.resolve():shutil.copy2(original,target)
    inventory=[descriptor(p,root) for p in sorted(root.rglob('*')) if p.is_file() and
      p.name not in ('OPEN_SUPPORT.html','SOURCE_FILES.json','source-manifest.json') and '__pycache__' not in p.parts]
    (root/'SOURCE_FILES.json').write_text(json.dumps({'schema':'upstate.source-file-inventory/v1','files':inventory},indent=2)+'\n')
    render(root)
    summary=json.loads((root/'support-summary.json').read_text())
    def entry(p:Path,key:str,title:str,kind:str,metadata:dict|None=None) -> dict:
        d=descriptor(p,root)
        return {'id':key,'title':title,'kind':kind,'role':'GEOGRAPHIC_SUPPORT',
          'uri':'urn:sha256:'+d['sha256'],'vintage':'Original retained source editions; compiled 2026-10-13',**d,
          'metadata':metadata or {}}
    primary=entry(root/'OPEN_SUPPORT.html','geographic-support-model-grid-20261013','Upper Savannah model-grid geographic supports','document',
      {'source_project_id':summary['source_project_id'],'grid':summary['grid'],'purpose':'Editable source support and independent memberships'})
    primary['companions']=[descriptor(p,root) for p in sorted(root.rglob('*')) if p.is_file() and
      p.name not in ('OPEN_SUPPORT.html','source-manifest.json') and '__pycache__' not in p.parts]
    rows={x['scope_id']:x for x in summary['scopes']}
    entries=[primary]
    for p in sorted((root/'rasters').glob('*.tif')):
        k=p.stem;entries.append(entry(p,'model-grid-'+k+'-20261013',rows.get(k,{}).get('title',k.replace('-',' ').replace('_',' ')),'raster',
          {'grid':summary['grid'],'scope':rows.get(k,{}),'values':'0 outside; 1 inside' if k not in ('huc12-zones','scope-membership') else 'See source inventory and crosswalk'}))
    entries.append(entry(root/'vectors/geographic-support.gpkg','geographic-support-vectors-20261013','Original and working geographic support layers','vector'))
    entries.append(entry(root/'tables/huc12-zones.csv','geographic-support-huc12-crosswalk-20261013','217 original HUC12 zone and scope crosswalk','table'))
    manifest={'schema':'upstate.sources/v1','title':'Upper Savannah 30 m geographic model support',
      'captured_at':datetime.now(timezone.utc).isoformat(),'entries':entries,
      'scope':{'source_project_id':summary['source_project_id'],'grid':summary['grid'],'masks':12,'original_huc12':217},
      'notes':['Independent source memberships on the retained HW13 grid.','Original sources and derived working repairs are retained separately.','Native quantities require this exact grid; source support does not supply model results.']}
    (root/'source-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print(json.dumps({'status':'HANDOFF_READY','entries':len(entries),'files':len(primary['companions'])+2,
      'viewer_bytes':(root/'OPEN_SUPPORT.html').stat().st_size,'manifest':str(root/'source-manifest.json')}))
    return manifest
if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('root',type=Path);args=parser.parse_args();prepare(args.root.resolve(strict=True))

#!/usr/bin/env python3
"""Produce a portable geographic-support source view from completed original data."""
import argparse,base64,csv,html,json,mimetypes,shutil
from pathlib import Path
import geopandas as gpd
from shapely.geometry import MultiPolygon,Polygon
from compile_grid_support import SCOPES,save_json,digest

def path_data(g,bounds,w=900,h=720):
    xmin,ymin,xmax,ymax=bounds;scale=min((w-48)/(xmax-xmin),(h-48)/(ymax-ymin))
    dx=(w-(xmax-xmin)*scale)/2;dy=(h-(ymax-ymin)*scale)/2
    def ring(r):
        coords=list(r.coords)
        return 'M'+'L'.join(f'{dx+(x-xmin)*scale:.2f},{h-dy-(y-ymin)*scale:.2f}' for x,y,*_ in coords)+'Z'
    polys=list(g.geoms) if isinstance(g,MultiPolygon) else [g] if isinstance(g,Polygon) else []
    return ''.join(ring(p.exterior)+''.join(ring(r) for r in p.interiors) for p in polys)

def render(root):
    summary=json.loads((root/'support-summary.json').read_text());gpkg=root/'vectors/geographic-support.gpkg'
    hucs=gpd.read_file(gpkg,layer='huc12_full_5070_working');bounds=summary['grid']['bounds']
    # Normalize only the view payload; the original computed source summary stays unchanged.
    for item in summary['scopes']:
        item['model_domain_area_ha']=item['in_model_domain_cells']*summary['grid']['pixel_area_ha']
        item['source_selection']=item['basis']
    for item in summary['huc12']:item['model_domain_cells']=item['grid_cells']
    summary['runtime']['peak_rss_mb']=summary['runtime']['max_resident_mb']
    def read_csv(name):
        with (root/'tables'/name).open(newline='') as stream:
            rows=list(csv.DictReader(stream))
        for row in rows:
            for key in ('class_code','cells','area_ha','percent_of_valid_scope','in_model_domain_cells','in_model_domain_area_ha','zone_id'):
                if key in row:row[key]=float(row[key]) if key not in ('class_code','cells','in_model_domain_cells','zone_id') else int(row[key])
        return rows
    summary['landcover']=read_csv('scope-landcover.csv')
    summary['huc_landcover']=read_csv('huc12-scope-landcover.csv')
    # Only the displayed SVG is simplified. All numeric calculations and GPKG retain full geometry.
    paths=[]
    for _,r in hucs.iterrows():
        paths.append(f'<path class="huc" data-huc="{r.huc12}" d="{path_data(r.geometry.simplify(60,preserve_topology=True),bounds)}"><title>{html.escape(r.huc12+" | "+r["name"])}</title></path>')
    layers={}
    for key in ('model_domain','sc_reporting','arjws_upstream','prwd_upstream','focus_huc12'):
        df=gpd.read_file(gpkg,layer={'model_domain':'huc12_full_5070_working','sc_reporting':'sc_reporting_original_5070_working'}.get(key,key)).to_crs(summary['grid']['crs'])
        layers[key]=''.join(path_data(g.simplify(45,preserve_topology=True),bounds) for g in df.geometry)
    df=gpd.read_file(gpkg,layer='protection_original_5070_working')
    for _,r in df.iterrows():layers['swpa_'+str(int(r.OBJECTID))]=path_data(r.geometry.simplify(15,preserve_topology=True),bounds)
    downloads={}
    selected=list((root/'rasters').glob('*.tif'))+[root/'vectors/geographic-support.gpkg']+list((root/'tables').glob('*.csv'))
    selected += [root/'originals/nlcd2025/land-cover.tif',root/'tables/geometry-working-repairs.json']
    if (root/'SOURCE_FILES.json').is_file():selected.append(root/'SOURCE_FILES.json')
    for p in selected:
        downloads[p.relative_to(root).as_posix()]={'mime':mimetypes.guess_type(p.name)[0] or 'application/octet-stream','base64':base64.b64encode(p.read_bytes()).decode('ascii')}
    payload={**summary,'map_layers':layers,'downloads':downloads,'display_m_to_svg':min(852/(bounds[2]-bounds[0]),672/(bounds[3]-bounds[1]))}
    packed=json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
    page=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Upper Savannah | Land-cover source workspace</title>
<style>
