.workspace{grid-template-areas:"map controls" "map detail";grid-template-rows:auto 1fr;row-gap:14px}.mapbox{grid-area:map}.panel{grid-area:detail}.scope-control{grid-area:controls}.map-tools{display:flex;gap:8px;margin-top:9px}.map-tools button{flex:1;font-size:13px;padding:8px}.mapbox svg{max-height:565px}#map-geometry .huc,#active-layer{vector-effect:non-scaling-stroke}
