function showScope(id){const s=D.scopes.find(s=>s.scope_id===id);$('scope').value=id;$('scopeTitle').textContent=s.title;$('scopeBasis').textContent=s.source_selection;$('legend').textContent=s.title;$('active-layer').setAttribute('d',D.map_layers[id]);$('scopeDetail').replaceChildren();for(const [label,value] of [['Included grid cells',fmt(s.grid_cells)],['Grid-cell area',fmt(s.grid_area_ha,2)+' ha'],['Area inside model',fmt(s.model_domain_area_ha,2)+' ha'],['Outside model',fmt(s.outside_model_domain_cells)+' cells'],['Projected vector area',fmt(s.projected_vector_area_ha,2)+' ha']]){$('scopeDetail').append(make('dt',label),make('dd',value));}$('maskDownload').href='rasters/'+id+'.tif';}
