function fitScope(){const box=$('active-layer').getBBox();if(!box.width||!box.height)return;const z=Math.min(830/box.width,610/box.height);$('map-geometry').setAttribute('transform',`matrix(${z} 0 0 ${z} ${(900-box.width*z)/2-box.x*z} ${(650-box.height*z)/2-box.y*z+15})`);const maxM=170/(D.display_m_to_svg*z),power=Math.pow(10,Math.floor(Math.log10(maxM))),candidate=[1,2,5].map(v=>v*power).filter(v=>v<=maxM),m=candidate[candidate.length-1]||power/2;$('scale-line').setAttribute('x2',50+m*D.display_m_to_svg*z);$('scale-text').textContent=m>=1000?fmt(m/1000,2).replace(/\.00$/,'')+' km':fmt(m)+' m';}
$('fitScope').addEventListener('click',fitScope);$('fullDomain').addEventListener('click',fullDomain);$('scope').addEventListener('change',e=>{showScope(e.target.value);fullDomain();});
