(() => {
const study=JSON.parse(document.getElementById('study').textContent),schema='upstate.scenario-margin-review/v1';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=2)=>Number.isFinite(v)?(v!==0&&Math.abs(v)<10**(-d)?v.toExponential(Math.min(d,6)):v.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d})):'Not defined';
const metrics=Object.keys(study.profiles[0].metrics),ids=study.profiles.map(p=>p.id),emptyCost=()=>({capital:'',annual:'',years:'',rate:'',title:'',uri:'',as_of:''});
function initial(){return {schema,source_id:study.source_id,profile:ids[0],included:[...ids],metric:metrics[0],layer:3,ratio:'1',currency:'USD',costs:{treatment:emptyCost(),control:emptyCost()},targets:Object.fromEntries(metrics.map(k=>[k,''])),decision:'review',notes:'',reviewer:'',source_filter:''};}
let state=initial(),storage=false,cache=new Map(),reviewRequest=0,editRevision=0;
function valid(x){
 if(!x||x.schema!==schema||x.source_id!==study.source_id)throw Error('Choose a saved review for this exact original source edition.');
 if(!ids.includes(x.profile)||!metrics.includes(x.metric)||![0,1,2,3,4].includes(x.layer)||!Array.isArray(x.included)||!x.included.length||new Set(x.included).size!==x.included.length||x.included.some(id=>!ids.includes(id)))throw Error('The saved review has an unavailable original profile, map or metric.');
 if(!/^[A-Z]{3}$/.test(x.currency)||!['review','treatment','control','neither'].includes(x.decision))throw Error('The saved review has an invalid currency or decision.');
 if(!x.costs||!x.targets)throw Error('Saved cost and target inputs are missing.');
 const n=initial();for(const k of ['profile','metric','layer','ratio','currency','decision','notes','reviewer','source_filter'])if(k in x)n[k]=x[k];n.included=[...x.included];
 for(const k of ['ratio','notes','reviewer','source_filter'])if(typeof n[k]!=='string')throw Error('Saved text inputs have an invalid type.');
 for(const c of ['treatment','control'])for(const k of Object.keys(n.costs[c])){if(typeof x.costs[c]?.[k]!=='string')throw Error('Saved quote fields must retain their original text.');n.costs[c][k]=x.costs[c][k];}
 for(const k of metrics){if(typeof x.targets[k]!=='string')throw Error('Saved target fields must be text.');n.targets[k]=x.targets[k];}
 return n;
}
try{const embedded=JSON.parse($('#saved').textContent);if(embedded)state=valid(embedded);else{const raw=localStorage.getItem(schema+'/'+study.source_id);if(raw)state=valid(JSON.parse(raw));}storage=true;}catch(e){storage=false;}
function remember(){try{localStorage.setItem(schema+'/'+study.source_id,JSON.stringify(state));storage=true;}catch{storage=false;}$('#storage').textContent=storage?'Browser copy available. Save a review file or full desk for independent receiving.':'This browser does not retain local storage. Save a review file or full desk to keep your edits.';}
