function number(text,label,{positive=false}={}){if(String(text).trim()==='')return null;const n=Number(text);if(!Number.isFinite(n)||n<0||(positive&&n<=0))throw Error(label+' must be a '+(positive?'positive':'nonnegative')+' finite number.');return n;}
function cost(side){const raw=state.costs[side],numbers=['capital','annual','years','rate'],entered=numbers.filter(k=>raw[k].trim()!=='');if(!entered.length)return {state:'unentered'};if(entered.length!==4)return {state:'incomplete',message:'Enter capital, annual operation, service years and discount rate together. Explicit zero is permitted.'};const capital=number(raw.capital,'Capital'),annual=number(raw.annual,'Annual operation'),years=number(raw.years,'Service years',{positive:true}),rate=number(raw.rate,'Discount rate')/100;const factor=rate===0?years:-Math.expm1(-years*Math.log1p(rate))/rate;const annualized=capital/factor+annual,present=capital+annual*factor;if(!Number.isFinite(annualized)||!Number.isFinite(present))throw Error('The entered cost assumptions exceed numeric range.');return {state:'priced',capital,annual,years,rate,annuity_factor:factor,annualized,present};}
